import React, { useState } from 'react';
import { ChevronDown, ChevronRight, FileCode, Lightbulb } from 'lucide-react';
import type { QualityIssue } from '../types';

interface QualityIssuesListProps {
  issues: QualityIssue[];
}

const severityStyles: Record<string, { badge: string; text: string }> = {
  critical: { badge: 'bg-red-200 dark:bg-red-900/50 text-red-800 dark:text-red-300', text: 'Critical' },
  major: { badge: 'bg-orange-200 dark:bg-orange-900/50 text-orange-800 dark:text-orange-300', text: 'Major' },
  minor: { badge: 'bg-yellow-200 dark:bg-yellow-900/50 text-yellow-800 dark:text-yellow-300', text: 'Minor' },
  info: { badge: 'bg-blue-200 dark:bg-blue-900/50 text-blue-800 dark:text-blue-300', text: 'Info' },
};

export const QualityIssuesList: React.FC<QualityIssuesListProps> = ({ issues }) => {
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());
  const [expandedIssues, setExpandedIssues] = useState<Set<string>>(new Set());

  // Group issues by category
  const groupedIssues = issues.reduce((acc, issue) => {
    if (!acc[issue.category]) {
      acc[issue.category] = [];
    }
    acc[issue.category].push(issue);
    return acc;
  }, {} as Record<string, QualityIssue[]>);

  const toggleCategory = (category: string) => {
    const newExpanded = new Set(expandedCategories);
    if (newExpanded.has(category)) {
      newExpanded.delete(category);
    } else {
      newExpanded.add(category);
    }
    setExpandedCategories(newExpanded);
  };

  const toggleIssue = (issueKey: string) => {
    const newExpanded = new Set(expandedIssues);
    if (newExpanded.has(issueKey)) {
      newExpanded.delete(issueKey);
    } else {
      newExpanded.add(issueKey);
    }
    setExpandedIssues(newExpanded);
  };

  if (issues.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500 dark:text-gray-400">
        No issues found
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {Object.entries(groupedIssues).map(([category, categoryIssues]) => {
        const isExpanded = expandedCategories.has(category);

        return (
          <div key={category} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
            <button
              onClick={() => toggleCategory(category)}
              className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800/50 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            >
              <div className="flex items-center gap-2">
                {isExpanded ? (
                  <ChevronDown className="h-4 w-4 text-gray-500" />
                ) : (
                  <ChevronRight className="h-4 w-4 text-gray-500" />
                )}
                <span className="font-medium text-gray-900 dark:text-gray-100">{category}</span>
                <span className="text-sm text-gray-500 dark:text-gray-400">
                  ({categoryIssues.length} {categoryIssues.length === 1 ? 'issue' : 'issues'})
                </span>
              </div>
            </button>

            {isExpanded && (
              <div className="divide-y divide-gray-200 dark:divide-gray-700">
                {categoryIssues.map((issue, idx) => {
                  const issueKey = `${category}-${idx}`;
                  const isIssueExpanded = expandedIssues.has(issueKey);
                  const severity = severityStyles[issue.severity] || severityStyles.info;

                  return (
                    <div key={issueKey} className="bg-white dark:bg-gray-900">
                      <button
                        onClick={() => toggleIssue(issueKey)}
                        className="w-full p-3 text-left hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors"
                      >
                        <div className="flex items-start gap-2">
                          <span className={`px-2 py-0.5 text-xs font-medium rounded ${severity.badge}`}>
                            {severity.text}
                          </span>
                          <div className="flex-1 min-w-0">
                            <p className="text-sm text-gray-900 dark:text-gray-100 line-clamp-2">
                              {issue.message}
                            </p>
                            <div className="flex items-center gap-1 mt-1 text-xs text-gray-500 dark:text-gray-400">
                              <FileCode className="h-3 w-3" />
                              <span className="truncate">
                                {issue.file}
                                {issue.line && `:${issue.line}`}
                              </span>
                            </div>
                          </div>
                          {isIssueExpanded ? (
                            <ChevronDown className="h-4 w-4 text-gray-400 flex-shrink-0" />
                          ) : (
                            <ChevronRight className="h-4 w-4 text-gray-400 flex-shrink-0" />
                          )}
                        </div>
                      </button>

                      {isIssueExpanded && issue.suggestion && (
                        <div className="px-3 pb-3">
                          <div className="flex items-start gap-2 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                            <Lightbulb className="h-4 w-4 text-blue-500 flex-shrink-0 mt-0.5" />
                            <p className="text-sm text-blue-800 dark:text-blue-200">
                              {issue.suggestion}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default QualityIssuesList;
