import React from 'react';
import { cn } from '@/lib/utils';
import type { TestPlan } from '../types';

interface TestPlanBadgeProps {
  testPlan?: TestPlan;
  compact?: boolean;
  className?: string;
}

interface CategoryBadgeProps {
  emoji: string;
  label: string;
  count: number;
  passing: number;
  compact?: boolean;
}

const CategoryBadge: React.FC<CategoryBadgeProps> = ({ emoji, label, count, passing, compact }) => {
  if (count === 0) return null;

  const allPassing = passing === count;
  const somePassing = passing > 0 && passing < count;

  return (
    <div
      className={cn(
        'inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium',
        allPassing && 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300',
        somePassing && 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300',
        !allPassing && !somePassing && 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300'
      )}
      title={`${label}: ${passing}/${count} passing`}
    >
      <span>{emoji}</span>
      <span>{count}</span>
      {!compact && (
        <span className="ml-0.5">
          {allPassing ? '✓' : somePassing ? `${passing}/${count}` : '✗'}
        </span>
      )}
    </div>
  );
};

const TestPlanBadge: React.FC<TestPlanBadgeProps> = ({ testPlan, compact = false, className }) => {
  if (!testPlan) {
    return (
      <span className={cn('text-xs text-muted-foreground', className)}>
        No test plan
      </span>
    );
  }

  const regression = testPlan.regression || [];
  const amended = testPlan.amended || [];
  const newTests = testPlan.newTests || [];

  const regressionPassing = regression.filter(t => t.status === 'passing').length;
  const amendedPassing = amended.filter(t => t.status === 'passing').length;
  const newPassing = newTests.filter(t => t.status === 'passing').length;

  const totalTests = regression.length + amended.length + newTests.length;
  const totalPassing = regressionPassing + amendedPassing + newPassing;

  if (totalTests === 0) {
    return (
      <span className={cn('text-xs text-muted-foreground', className)}>
        No tests defined
      </span>
    );
  }

  return (
    <div className={cn('flex items-center gap-1.5 flex-wrap', className)}>
      <CategoryBadge
        emoji="🔒"
        label="Regression"
        count={regression.length}
        passing={regressionPassing}
        compact={compact}
      />
      <CategoryBadge
        emoji="✏️"
        label="Amended"
        count={amended.length}
        passing={amendedPassing}
        compact={compact}
      />
      <CategoryBadge
        emoji="🆕"
        label="New"
        count={newTests.length}
        passing={newPassing}
        compact={compact}
      />
      {!compact && (
        <span className="text-xs text-muted-foreground ml-1">
          ({totalPassing}/{totalTests} passing)
        </span>
      )}
    </div>
  );
};

export default TestPlanBadge;
