import React, { useMemo } from 'react';
import { cn } from '@/lib/utils';
import ProgressBar from './ProgressBar';
import { SelectableCard } from './ui/selectable-card';
import type { Plan } from '../types';

// Format date to relative time
function formatRelativeTime(dateStr: string | undefined): string {
  if (!dateStr) return 'Never';
  
  const date = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffMinutes = Math.floor(diffMs / (1000 * 60));
  
  if (diffMinutes < 1) return 'Just now';
  if (diffMinutes < 60) return `${diffMinutes}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} ${diffDays === 1 ? 'day' : 'days'} ago`;
  if (diffDays < 30) {
    const weeks = Math.floor(diffDays / 7);
    return `${weeks} ${weeks === 1 ? 'week' : 'weeks'} ago`;
  }
  if (diffDays < 365) {
    const months = Math.floor(diffDays / 30);
    if (months === 1 && diffDays > 30) {
      return 'over a month ago';
    }
    return `${months} ${months === 1 ? 'month' : 'months'} ago`;
  }
  const years = Math.floor(diffDays / 365);
  return `${years} ${years === 1 ? 'year' : 'years'} ago`;
}

interface PlanCardProps {
  plan: Plan;
  isSelected: boolean;
  onClick: () => void;
}

const PlanCard: React.FC<PlanCardProps> = ({ plan, isSelected, onClick }) => {
  const planName = plan.title || plan.name || 'Unnamed Plan';
  const updatedDate = formatRelativeTime(plan.updatedAt || plan.lastUpdated);

  // Calculate progress from tasks (same logic as PlanDetailsPRD)
  // This ensures sidebar and detailed view are always in sync
  const { progress, completedPercent, supersededPercent } = useMemo(() => {
    const features = plan.features || [];
    const totalTasks = features.reduce((acc, feature) => acc + (feature.tasks?.length || 0), 0);
    const completedTasks = features.reduce(
      (acc, feature) => acc + (feature.tasks?.filter(task => task.status === 'completed').length || 0),
      0
    );
    const supersededTasks = features.reduce(
      (acc, feature) => acc + (feature.tasks?.filter(task => task.status === 'superseded').length || 0),
      0
    );
    const doneTasks = completedTasks + supersededTasks;

    return {
      progress: totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0,
      completedPercent: totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0,
      supersededPercent: totalTasks > 0 ? Math.round((supersededTasks / totalTasks) * 100) : 0,
    };
  }, [plan.features]);

  // Calculate feature count from features array or metadata
  const featureCount = plan.features?.length ?? plan.metadata?.totalFeatures ?? plan.featureCount ?? 0;

  const isComplete = progress === 100;
  const isInProgress = plan.status === 'in_progress';

  return (
    <SelectableCard
      isSelected={isSelected}
      isCompleted={isComplete}
      onClick={onClick}
      className="relative overflow-hidden"
    >
      
      <div className="flex items-start justify-between mb-2 gap-2">
        <h3 className="font-semibold text-sm line-clamp-2 text-text-primary dark:text-gray-200">
          {planName}
        </h3>
        {plan.isTheCurrentPlan && <span className="text-sm">⭐</span>}
      </div>
      
      <div className="space-y-2">
        <div className={cn("flex justify-between text-xs",
          isComplete ? "text-green-700 dark:text-green-300 font-medium" :
          isSelected ? "text-gray-700 dark:text-gray-300" 
            : "text-text-secondary dark:text-gray-400"
        )}>
          <span>{isComplete ? '✅ Complete!' : 'Progress'}</span>
          <span className={isComplete ? "font-bold" : ""}>{progress}%</span>
        </div>
        <ProgressBar
          progress={progress}
          isSelected={isSelected}
          isInProgress={isInProgress}
          completedPercent={completedPercent}
          supersededPercent={supersededPercent}
        />
      </div>

      <div className="flex justify-between items-center mt-3 text-xs text-muted-foreground">
        <span>📊 {featureCount} features</span>
        <span>{updatedDate}</span>
      </div>
    </SelectableCard>
  );
};

export default PlanCard;