import { useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import { Drama, Clock, CheckCircle, Archive } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { ResizablePanel, ResizablePanelGroup, ResizableHandle } from '@/components/ui/resizable'
import PlanList from '@/components/PlanList'
import PlanDetails from '@/components/PlanDetails'
import PlanActions from '@/components/PlanActions'
import { useSSE } from '@/hooks/useSSE'
import type { Plan } from '@/types'

export default function PersonaDetailPage() {
  const { personaId } = useParams<{ personaId: string }>()
  const sseState = useSSE()
  const currentPersona = sseState.personaId || 'default'
  const [selectedPlanId, setSelectedPlanId] = useState<string | null>(null)
  const [viewMode, setViewMode] = useState<'summary' | 'details' | 'json'>('details')
  const [personaDetails, setPersonaDetails] = useState<any>(null)
  const [personaPlans, setPersonaPlans] = useState<Plan[]>([])
  const [loading, setLoading] = useState(true)
  const [showArchived, setShowArchived] = useState(false)

  const isActivePersona = personaId === currentPersona

  // Use SSE plans only if this is the active persona and SSE is connected
  const allPlans = (isActivePersona && sseState.isConnected) ? sseState.plans : personaPlans

  // Filter plans based on archived toggle
  const plans = showArchived ? allPlans : allPlans.filter(p => p.type !== 'archived')

  const selectedPlan = selectedPlanId ? plans.find((p: Plan) => p.id === selectedPlanId) : null

  // Fetch plans for specific persona
  const fetchPersonaPlans = async () => {
    try {
      const response = await fetch(`/api/personas/${personaId}/plans`)
      if (response.ok) {
        const data = await response.json()
        setPersonaPlans(data.plans || [])
      }
    } catch (error) {
      console.error('Error fetching persona plans:', error)
    }
  }

// Fetch persona details
  useEffect(() => {
    const fetchPersonaDetails = async () => {
      try {
        setLoading(true)
        const response = await fetch(`/api/personas/${personaId}`)
        if (response.ok) {
          const data = await response.json()
          setPersonaDetails(data)
        } else {
          console.error('Failed to fetch persona details:', response.statusText)
          setPersonaDetails({
            name: personaId,
            description: 'Persona configuration',
            lastUsed: new Date().toISOString()
          })
        }
      } catch (error) {
        console.error('Error fetching persona details:', error)
        setPersonaDetails({
          name: personaId,
          description: 'Persona configuration',
          lastUsed: new Date().toISOString()
        })
      } finally {
        setLoading(false)
      }
    }

    if (personaId) {
      fetchPersonaDetails()
      // Always fetch plans initially
      // For active persona, SSE will take over once connected
      fetchPersonaPlans()
    }
  }, [personaId])

  // Auto-select first plan
  useEffect(() => {
    if (plans.length > 0 && !selectedPlanId) {
      setSelectedPlanId(plans[0].id)
    }
  }, [plans, selectedPlanId])

  // Listen for SSE plan updates if this is the active persona
  useEffect(() => {
    if (isActivePersona && sseState.isConnected) {
      // The file watcher is already running and sending updates via SSE
      // The useSSE hook will automatically update sseState.plans
      console.log('Watching plans for active persona:', personaId)
    }

    return () => {
      // Cleanup: The SSE connection remains open for other components
      // The file watcher continues running server-side
      console.log('Stopped watching plans for persona:', personaId)
    }
  }, [isActivePersona, personaId, sseState.isConnected])

  const getPersonaIcon = (name: string | undefined) => {
    const colors = [
      'bg-orange-100 dark:bg-orange-900/20 text-orange-500',
      'bg-blue-100 dark:bg-blue-900/20 text-blue-500',
      'bg-purple-100 dark:bg-purple-900/20 text-purple-500',
      'bg-green-100 dark:bg-green-900/20 text-green-500',
      'bg-pink-100 dark:bg-pink-900/20 text-pink-500',
    ]
    if (!name || typeof name !== 'string' || name.length === 0) {
      return colors[0]
    }
    const colorIndex = name.charCodeAt(0) % colors.length
    return colors[colorIndex]
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header with persona details */}
      <div className="border-b">
        <div className="p-4 md:p-6">
          {/* Persona details */}
          {loading ? (
            <div className="animate-pulse">
              <div className="h-8 w-48 bg-gray-200 dark:bg-gray-700 rounded mb-2" />
              <div className="h-4 w-64 bg-gray-200 dark:bg-gray-700 rounded" />
            </div>
          ) : (
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-4">
                <div className={`p-3 rounded-lg ${getPersonaIcon(personaId)}`}>
                  <Drama className="h-8 w-8" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold">{personaId}</h1>
                  <p className="text-muted-foreground">
                    {personaDetails?.persona?.system?.metadata?.description ||
                     personaDetails?.metadata?.description ||
                     'Persona configuration'}
                  </p>
                  <div className="flex items-center gap-4 mt-2">
                    {isActivePersona && (
                      <Badge variant="default" className="text-xs bg-primary">
                        <CheckCircle className="h-3 w-3 mr-1" />
                        Active
                      </Badge>
                    )}
                    {personaDetails?.metadata?.lastUpdated && (
                      <div className="flex items-center gap-1 text-xs text-muted-foreground">
                        <Clock className="h-3 w-3" />
                        Last updated: {new Date(personaDetails.metadata.lastUpdated).toLocaleDateString()}
                      </div>
                    )}
                    {personaDetails?.planCount !== undefined && (
                      <Badge variant="secondary" className="text-xs">
                        {personaDetails.planCount} plan{personaDetails.planCount !== 1 ? 's' : ''}
                      </Badge>
                    )}
                  </div>
                </div>
              </div>

            </div>
          )}
        </div>
      </div>

      {/* Plans section with sidebar */}
      <div className="flex-1 overflow-hidden">
        <ResizablePanelGroup direction="horizontal" className="h-full">
          <ResizablePanel defaultSize={30} minSize={20} maxSize={40}>
            <div className="h-full border-r">
              <div className="p-4 border-b bg-gray-50 dark:bg-gray-900">
                <div className="flex items-center justify-between">
                  <h3 className="font-semibold">Plans ({plans.length})</h3>
                  {/* Archive toggle button */}
                  <button
                    onClick={() => setShowArchived(!showArchived)}
                    className={`px-3 py-2.5 rounded transition-colors ${
                      showArchived
                        ? 'bg-primary text-primary-foreground'
                        : 'hover:bg-muted text-muted-foreground'
                    }`}
                    title={showArchived ? 'Hide archived plans' : 'Show archived plans'}
                  >
                    <Archive className="h-4 w-4" />
                  </button>
                </div>
              </div>
              <div className="overflow-auto h-[calc(100%-89px)]">
                <PlanList
                  plans={plans}
                  selectedPlanId={selectedPlanId}
                  onSelectPlan={setSelectedPlanId}
                />
              </div>
            </div>
          </ResizablePanel>

          <ResizableHandle />

          <ResizablePanel defaultSize={70}>
            <div className="h-full flex flex-col">
              {selectedPlan ? (
                <>
                  {/* Plan Actions Toolbar */}
                  <div className="border-b p-4 bg-gray-50 dark:bg-gray-900">
                    <div className="flex items-center justify-between m-px">
                      <h3 className="font-semibold">{selectedPlan.title || selectedPlan.name}</h3>
                      <div className="flex items-center gap-3">
                        {/* View mode toggle */}
                        <div className="flex rounded-lg border border-input overflow-hidden">
                          <button
                            className={`px-3 py-1.5 text-sm font-medium transition-colors ${
                              viewMode === 'details'
                                ? 'bg-primary text-primary-foreground'
                                : 'bg-background hover:bg-muted'
                            }`}
                            onClick={() => setViewMode('details')}
                          >
                            Details
                          </button>
                          <button
                            className={`px-3 py-1.5 text-sm font-medium transition-colors border-l border-input ${
                              viewMode === 'summary'
                                ? 'bg-primary text-primary-foreground'
                                : 'bg-background hover:bg-muted'
                            }`}
                            onClick={() => setViewMode('summary')}
                          >
                            Summary
                          </button>
                          <button
                            className={`px-3 py-1.5 text-sm font-medium transition-colors border-l border-input ${
                              viewMode === 'json'
                                ? 'bg-primary text-primary-foreground'
                                : 'bg-background hover:bg-muted'
                            }`}
                            onClick={() => setViewMode('json')}
                          >
                            JSON
                          </button>
                        </div>
                        <PlanActions selectedPlan={selectedPlan} />
                      </div>
                    </div>
                  </div>
                  {/* Plan Details */}
                  <div className="flex-1 overflow-auto">
                    <PlanDetails plan={selectedPlan} viewMode={viewMode} personaId={personaId} />
                  </div>
                </>
              ) : (
                <div className="flex items-center justify-center h-full">
                  <div className="text-center">
                    <p className="text-muted-foreground">No plan selected</p>
                    <p className="text-sm text-muted-foreground mt-2">
                      Select a plan from the sidebar to view details
                    </p>
                  </div>
                </div>
              )}
            </div>
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>
    </div>
  )
}