import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { Label } from './ui/label';
import { Input } from './ui/input';
import { Key, Monitor } from 'lucide-react';
import { getStoredCredentials } from '../services/api';

const SettingsPane: React.FC = () => {
  const [clientId, setClientId] = useState('');
  const [clientSecret, setClientSecret] = useState('');
  const [hasStoredCredentials, setHasStoredCredentials] = useState(false);

  // Check for stored credentials via API endpoint
  const checkStoredCredentials = async () => {
    try {
      const data = await getStoredCredentials();
      if (data.clientId && data.clientSecret === '[STORED]') {
        setClientId(data.clientId);
        setClientSecret('[STORED]'); // Show that secret is stored
        setHasStoredCredentials(true);
        return true;
      }
    } catch (err) {
      console.error('Failed to check stored credentials:', err);
    }
    return false;
  };

  // Load credentials on mount
  React.useEffect(() => {
    const loadCredentials = async () => {
      const hasStored = await checkStoredCredentials();
      if (!hasStored) {
        // Fall back to localStorage if no CLI credentials
        const savedClientId = localStorage.getItem('tbl-client-id');
        const savedClientSecret = localStorage.getItem('tbl-client-secret');
        if (savedClientId) setClientId(savedClientId);
        if (savedClientSecret) setClientSecret(savedClientSecret);
      }
    };
    loadCredentials();
  }, []);

  return (
    <div className="p-8 max-w-6xl mx-auto">
      <h1 className="text-3xl font-bold mb-8">Settings</h1>
      
      {/* Getting Started Section - Only show if no credentials */}
      {!hasStoredCredentials && (
        <Card className="mb-6">
          <CardHeader>
            <div className="flex items-center gap-2">
              <Monitor className="h-5 w-5 text-blue-500" />
              <CardTitle>Getting Started</CardTitle>
            </div>
            <CardDescription>
              How to obtain your Tiny Brain credentials
            </CardDescription>
          </CardHeader>
          <CardContent>
            <ol className="text-sm text-gray-600 space-y-2">
              <li>1. Visit <a href="https://tiny-brain.com" target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:underline">tiny-brain.com</a></li>
              <li>2. Sign in to your account</li>
              <li>3. Navigate to Settings → API Keys</li>
              <li>4. Generate new credentials</li>
              <li>5. Copy your Client ID and Client Secret</li>
              <li>6. Set credentials using the CLI commands below</li>
            </ol>
          </CardContent>
        </Card>
      )}
      
      {/* Library Authentication Section */}
      <Card className="mb-6">
        <CardHeader>
          <div className="flex items-center gap-2">
            <Key className="h-5 w-5 text-green-500" />
            <CardTitle>Library Authentication</CardTitle>
          </div>
          <CardDescription>
            {hasStoredCredentials
              ? 'Your credentials are securely stored in the system keychain'
              : 'Your API keys for connecting to the Tiny Brain Library'
            }
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="client-id">Client ID</Label>
            <Input
              id="client-id"
              value={clientId}
              readOnly
              placeholder="No credentials configured"
              className="font-mono bg-muted"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="client-secret">Client Secret</Label>
            <Input
              id="client-secret"
              type="text"
              value={clientSecret}
              readOnly
              placeholder={hasStoredCredentials ? 'Secret is stored securely' : 'No secret configured'}
              className="font-mono bg-muted"
            />
          </div>

          {/* CLI Instructions */}
          <div className="p-3 rounded-lg bg-muted text-sm space-y-2">
            <p className="font-medium">Manage credentials via CLI:</p>
            <div className="font-mono space-y-1 text-xs">
              <p className="text-muted-foreground"># Set credentials</p>
              <p>tiny-brain config set clientId YOUR_ID</p>
              <p>tiny-brain config set clientSecret YOUR_SECRET</p>
              <p className="text-muted-foreground mt-2"># Clear credentials</p>
              <p>tiny-brain config clear</p>
            </div>
          </div>
        </CardContent>
      </Card>

    </div>
  );
};

export default SettingsPane;