import React from 'react';
import { LucideIcon, Circle, ArrowLeft } from 'lucide-react';
import { useLibrary } from '../../contexts/LibraryContext';
import { useLocation, useNavigate } from 'react-router-dom';

interface HeaderProps {
  isCollapsed: boolean;
  currentItem?: {
    title: string;
    icon: LucideIcon;
    color: string;
  };
}

export const Header: React.FC<HeaderProps> = ({
  isCollapsed,
  currentItem
}) => {
  const { connectionStatus } = useLibrary();
  const location = useLocation();
  const navigate = useNavigate();

  // Check if we're on a detail page
  const isPersonaDetailPage = location.pathname.match(/^\/personas\/[^/]+$/);
  const isRepoDetailPage = location.pathname.match(/^\/repos\/[^/]+$/);

  const getStatusColor = () => {
    switch (connectionStatus) {
      case 'connected': return 'text-green-500';
      case 'error': return 'text-red-500';
      case 'checking': return 'text-yellow-500 animate-pulse';
      default: return 'text-gray-400';
    }
  };
  return (
    <header className="h-16 border-b bg-white dark:bg-gray-900 flex">
      {/* Logo section - above sidebar */}
      <div className={`${isCollapsed ? 'w-16' : 'w-48'} transition-all duration-200 flex items-center justify-center px-4`}>
        <div className="flex items-center gap-3">
          <span className="text-2xl">🧠</span>
          {!isCollapsed && (
            <span className="font-semibold text-lg bg-gradient-to-r from-pink-500 to-blue-500 bg-clip-text text-transparent">tiny brain</span>
          )}
        </div>
      </div>

      {/* Main header section */}
      <div className="flex-1 flex items-center justify-between px-4">
        <div className="flex items-center">
          {isPersonaDetailPage ? (
            <button
              onClick={() => navigate('/personas')}
              className="flex items-center gap-2 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
            >
              <ArrowLeft className="h-4 w-4" />
              <span className="font-medium">Back to Personas</span>
            </button>
          ) : isRepoDetailPage ? (
            <button
              onClick={() => navigate('/repos')}
              className="flex items-center gap-2 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
            >
              <ArrowLeft className="h-4 w-4" />
              <span className="font-medium">Back to Repos</span>
            </button>
          ) : currentItem && (
            <div className="flex items-center gap-2">
              <currentItem.icon className={`h-5 w-5 ${currentItem.color}`} />
              <span className="font-medium">{currentItem.title}</span>
            </div>
          )}
        </div>
        
        {/* Library connection status */}
        <div className="flex items-center gap-2">
          <Circle className={`h-3 w-3 fill-current ${getStatusColor()}`} />
          <span className="text-sm text-gray-600 dark:text-gray-400">Library</span>
        </div>
      </div>
    </header>
  );
};