import React from 'react';
import { cn } from '@/lib/utils';
import { SelectableCard } from './ui/selectable-card';
import type { Fix } from '../types';

interface FixCardProps {
  fix: Fix;
  isSelected: boolean;
  onClick: () => void;
}

const severityColors = {
  low: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300',
  medium: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300',
  high: 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300',
  critical: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300',
};

const statusIcons = {
  investigating: '🔍',
  in_progress: '🔧',
  resolved: '✅',
};

const FixCard: React.FC<FixCardProps> = ({ fix, isSelected, onClick }) => {
  const completedTasks = fix.tasks.filter(t => t.status === 'completed' || t.status === 'superseded').length;
  const totalTasks = fix.tasks.length;
  const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
  const isResolved = fix.status === 'resolved';

  return (
    <SelectableCard isSelected={isSelected} isCompleted={isResolved} onClick={onClick}>
      <div className="flex items-start justify-between gap-2">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-sm" title={fix.status}>
              {statusIcons[fix.status]}
            </span>
            <h3 className="font-medium text-sm truncate">{fix.title}</h3>
          </div>
          <p className="text-xs text-muted-foreground truncate">
            {fix.id}
          </p>
        </div>
        <span className={cn(
          'text-xs px-2 py-0.5 rounded-full font-medium whitespace-nowrap',
          severityColors[fix.severity]
        )}>
          {fix.severity}
        </span>
      </div>

      {/* Progress bar */}
      {totalTasks > 0 && (
        <div className="mt-2">
          <div className="flex items-center justify-between text-xs text-muted-foreground mb-1">
            <span>Tasks: {completedTasks}/{totalTasks}</span>
            <span>{progress}%</span>
          </div>
          <div className="h-1.5 bg-muted rounded-full overflow-hidden">
            <div
              className={cn(
                'h-full rounded-full transition-all',
                fix.status === 'resolved' ? 'bg-green-500' : 'bg-primary'
              )}
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      )}

      {/* Date info */}
      {fix.reported && (
        <div className="mt-2 text-xs text-muted-foreground">
          Reported: {new Date(fix.reported).toLocaleDateString()}
          {fix.resolved && (
            <span className="ml-2">
              Resolved: {new Date(fix.resolved).toLocaleDateString()}
            </span>
          )}
        </div>
      )}
    </SelectableCard>
  );
};

export default FixCard;
