import React, { useMemo, useState } from 'react';
import type { Plan, Task } from '../types';
import { Card, CardContent } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { User, ChevronDown, ChevronRight } from 'lucide-react';
import ProgressDonutChart from './charts/ProgressDonutChart';
import FeatureDetail from './FeatureDetail';
import TaskDetailPanel from './TaskDetailPanel';
import clsx from 'clsx';

interface PlanDetailsPRDProps {
  plan: Plan;
  repoId?: string;
}

interface SelectedTask {
  featureId: string;
  taskNumber: number;
  progressTask: Task;
}

const PlanDetailsPRD: React.FC<PlanDetailsPRDProps> = ({ plan, repoId }) => {
  const [expandedFeatures, setExpandedFeatures] = useState<Set<number>>(new Set());
  const [selectedTask, setSelectedTask] = useState<SelectedTask | null>(null);

  const handleTaskClick = (featureId: string, taskNumber: number, progressTask: Task) => {
    setSelectedTask({ featureId, taskNumber, progressTask });
  };

  const handleCloseTaskPanel = () => {
    setSelectedTask(null);
  };

  const toggleFeature = (featureNumber: number) => {
    setExpandedFeatures(prev => {
      const next = new Set(prev);
      if (next.has(featureNumber)) {
        next.delete(featureNumber);
      } else {
        next.add(featureNumber);
      }
      return next;
    });
  };

  // Extract PRD information
  const prdInfo = useMemo(() => {
    return {
      id: plan.prdId || 'Unknown',
      path: plan.prdDirPath || 'Not specified',
      status: plan.status,
      created: plan.created,
      lastUpdated: plan.lastUpdated,
      creator: plan.gitUserName || plan.gitUserEmail || 'Unknown',
      creatorEmail: plan.gitUserEmail,
    };
  }, [plan]);

  // Extract features from plan
  const features = useMemo(() => plan.features || [], [plan.features]);

  // Auto-expand current in-progress feature
  React.useEffect(() => {
    const currentFeature = features.find(f => f.status === 'tested');
    if (currentFeature) {
      setExpandedFeatures(new Set([currentFeature.number]));
    }
  }, [features]);

  // Helper function for terminal statuses
  const isFeatureDone = (status: string) => status === 'completed' || status === 'superseded';

  // Calculate overall metrics
  const metrics = useMemo(() => {
    const totalTasks = features.reduce((acc, feature) => acc + (feature.tasks?.length || 0), 0);
    const actuallyCompletedTasks = features.reduce(
      (acc, feature) => acc + (feature.tasks?.filter(task => task.status === 'completed').length || 0),
      0
    );
    const supersededTasks = features.reduce(
      (acc, feature) => acc + (feature.tasks?.filter(task => task.status === 'superseded').length || 0),
      0
    );
    const doneTasks = actuallyCompletedTasks + supersededTasks;

    // A feature displays as superseded if:
    // - Feature status is 'superseded', OR
    // - Feature is 'completed' but ALL tasks are superseded
    const displayAsSupersededFeatures = features.filter(f => {
      if (f.status === 'superseded') return true;
      if (f.status === 'completed') {
        const totalFeatureTasks = f.tasks?.length || 0;
        const supersededFeatureTasks = f.tasks?.filter(t => t.status === 'superseded').length || 0;
        return totalFeatureTasks > 0 && supersededFeatureTasks === totalFeatureTasks;
      }
      return false;
    }).length;

    const displayAsCompletedFeatures = features.filter(f => {
      if (f.status !== 'completed') return false;
      const totalFeatureTasks = f.tasks?.length || 0;
      const supersededFeatureTasks = f.tasks?.filter(t => t.status === 'superseded').length || 0;
      // Not all tasks are superseded
      return !(totalFeatureTasks > 0 && supersededFeatureTasks === totalFeatureTasks);
    }).length;

    const doneFeatures = displayAsCompletedFeatures + displayAsSupersededFeatures;
    const inProgressFeatures = features.filter(f => f.status === 'tested').length;

    return {
      totalFeatures: features.length,
      completedFeatures: displayAsCompletedFeatures,
      supersededFeatures: displayAsSupersededFeatures,
      doneFeatures,
      inProgressFeatures,
      totalTasks,
      completedTasks: actuallyCompletedTasks,
      supersededTasks,
      doneTasks,
      progress: totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0,
    };
  }, [features]);


  return (
    <div className="h-full flex flex-col">
      {/* PRD Header Border */}
      <div className="border-b flex-shrink-0" />

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {/* Row 1: PRD Details + Progress */}
        <div className="grid grid-cols-2 gap-4">
          {/* Left: PRD Metadata */}
          <Card>
            <CardContent className="space-y-1 text-sm py-2">
              <div className="flex justify-between">
                <span className="text-muted-foreground">PRD ID:</span>
                <span className="font-mono text-xs">{prdInfo.id}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">Location:</span>
                <span className="font-mono text-xs truncate max-w-xs" title={prdInfo.path}>
                  {prdInfo.path}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-muted-foreground">Creator:</span>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <div className="flex items-center gap-1">
                        <User className="h-3 w-3" />
                        <span className="text-xs text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 cursor-pointer underline decoration-dotted">
                          {prdInfo.creator}
                        </span>
                      </div>
                    </TooltipTrigger>
                    {prdInfo.creatorEmail && (
                      <TooltipContent
                        className="bg-gray-800 dark:bg-gray-700 text-white border-gray-700"
                        arrowClassName="bg-gray-800 fill-gray-800 dark:bg-gray-700 dark:fill-gray-700"
                      >
                        <p>{prdInfo.creatorEmail}</p>
                      </TooltipContent>
                    )}
                  </Tooltip>
                </TooltipProvider>
              </div>
              <Separator className="my-1" />
              <div className="flex justify-between text-xs">
                <span className="text-muted-foreground">Created: <span className="text-foreground">{prdInfo.created ? new Date(prdInfo.created).toLocaleDateString() : 'Unknown'}</span></span>
                <span className="text-muted-foreground">Updated: <span className="text-foreground">{prdInfo.lastUpdated ? new Date(prdInfo.lastUpdated).toLocaleDateString() : 'Unknown'}</span></span>
              </div>
            </CardContent>
          </Card>

          {/* Right: Progress Overview */}
          <Card>
            <CardContent className="py-2">
              <div className="grid grid-cols-2 gap-4">
                {/* Features Donut Chart */}
                <div className="flex flex-col items-center justify-center">
                  <div className="w-24 h-24 relative">
                    <ProgressDonutChart
                      completed={metrics.completedFeatures}
                      superseded={metrics.supersededFeatures}
                      total={metrics.totalFeatures}
                      label="Features"
                    />
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                      <div className="text-center">
                        <div className="text-lg font-bold">{metrics.doneFeatures}/{metrics.totalFeatures}</div>
                      </div>
                    </div>
                  </div>
                  <div className="text-sm text-muted-foreground mt-2">Features</div>
                </div>

                {/* Tasks Donut Chart */}
                <div className="flex flex-col items-center justify-center">
                  <div className="w-24 h-24 relative">
                    <ProgressDonutChart
                      completed={metrics.completedTasks}
                      superseded={metrics.supersededTasks}
                      total={metrics.totalTasks}
                      label="Tasks"
                    />
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                      <div className="text-center">
                        <div className="text-lg font-bold">{metrics.doneTasks}/{metrics.totalTasks}</div>
                      </div>
                    </div>
                  </div>
                  <div className="text-sm text-muted-foreground mt-2">Tasks</div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Row 2: Collapsible Features List */}
        <div className="space-y-3">
          <h3 className="text-lg font-semibold">Features</h3>
          {features.map((feature) => {
            const totalTasks = feature.tasks?.length || 0;
            const completedTasks = feature.tasks?.filter(task => task.status === 'completed')?.length || 0;
            const supersededTasks = feature.tasks?.filter(task => task.status === 'superseded')?.length || 0;
            const doneTasks = completedTasks + supersededTasks;
            const hasSupersededTasks = supersededTasks > 0;

            // A feature displays as superseded if all tasks are superseded
            const allTasksSuperseded = totalTasks > 0 && supersededTasks === totalTasks;
            const displayAsSuperseded = feature.status === 'superseded' || (feature.status === 'completed' && allTasksSuperseded);
            const displayAsCompleted = feature.status === 'completed' && !allTasksSuperseded;

            const progress = isFeatureDone(feature.status) ? 100 :
                            totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
            const completedPercent = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
            const isExpanded = expandedFeatures.has(feature.number);

            return (
              <div
                key={feature.id}
                className={clsx(
                  'rounded-lg border overflow-hidden transition-all',
                  displayAsCompleted && !hasSupersededTasks && 'bg-green-100 dark:bg-green-900/30 border-green-300 dark:border-green-800',
                  displayAsCompleted && hasSupersededTasks && 'border-green-300 dark:border-green-800',
                  displayAsSuperseded && 'bg-orange-100 dark:bg-orange-900/30 border-orange-300 dark:border-orange-800',
                  feature.status === 'tested' && 'bg-blue-100 dark:bg-blue-900/30 border-blue-300 dark:border-blue-800',
                  feature.status === 'defined' && 'bg-gray-100 dark:bg-gray-800/50 border-gray-300 dark:border-gray-700'
                )}
              >
                {/* Feature Header - Clickable */}
                <div
                  onClick={() => toggleFeature(feature.number)}
                  className="relative p-4 cursor-pointer hover:opacity-80 transition-opacity"
                >
                  {/* Progress fill for in-progress features - only in header */}
                  {feature.status === 'tested' && progress > 0 && (
                    <div
                      className="absolute inset-0 bg-blue-200 dark:bg-blue-800/40 transition-all duration-300 pointer-events-none"
                      style={{ width: `${progress}%` }}
                    />
                  )}

                  {/* Mixed progress bar for completed features with some superseded tasks */}
                  {displayAsCompleted && hasSupersededTasks && totalTasks > 0 && (
                    <>
                      {/* Orange background for superseded portion */}
                      <div className="absolute inset-0 bg-orange-200 dark:bg-orange-800/40 pointer-events-none" />
                      {/* Green foreground for completed portion */}
                      <div
                        className="absolute inset-0 bg-green-200 dark:bg-green-800/40 transition-all duration-300 pointer-events-none"
                        style={{ width: `${completedPercent}%` }}
                      />
                    </>
                  )}
                  <div className="relative flex items-center justify-between gap-3">
                    <div className="flex items-center gap-3 min-w-0 flex-1">
                      {/* Expand/Collapse Icon */}
                      {isExpanded ? (
                        <ChevronDown className="h-5 w-5 flex-shrink-0" />
                      ) : (
                        <ChevronRight className="h-5 w-5 flex-shrink-0" />
                      )}

                      {/* Feature status icon */}
                      <div className="flex-shrink-0">
                        {displayAsCompleted && (
                          <span className="text-green-600 dark:text-green-400 text-lg">✓</span>
                        )}
                        {displayAsSuperseded && (
                          <span className="text-orange-600 dark:text-orange-400 text-lg">⏭</span>
                        )}
                        {feature.status === 'tested' && (
                          <span className="text-blue-600 dark:text-blue-400 text-lg">●</span>
                        )}
                        {feature.status === 'defined' && (
                          <span className="text-gray-400 dark:text-gray-500 text-lg">○</span>
                        )}
                      </div>

                      {/* Feature number badge */}
                      <div className={clsx(
                        "flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold",
                        displayAsCompleted && "bg-green-600 dark:bg-green-700 text-white",
                        displayAsSuperseded && "bg-orange-600 dark:bg-orange-700 text-white",
                        feature.status === 'tested' && "bg-blue-600 dark:bg-blue-700 text-white",
                        feature.status === 'defined' && "bg-gray-400 dark:bg-gray-600 text-white"
                      )}>
                        {feature.number}
                      </div>

                      {/* Feature info */}
                      <div className="min-w-0 flex-1">
                        <span className={clsx(
                          "text-lg font-semibold",
                          displayAsCompleted && "text-green-800 dark:text-green-200",
                          displayAsSuperseded && "text-orange-800 dark:text-orange-200 line-through",
                          feature.status === 'tested' && "text-blue-800 dark:text-blue-200",
                          feature.status === 'defined' && "text-gray-700 dark:text-gray-300"
                        )}>
                          {feature.title}
                        </span>
                      </div>
                    </div>

                    {/* Task count */}
                    <div className={clsx(
                      "text-sm ml-3 flex-shrink-0",
                      displayAsCompleted && "text-green-600 dark:text-green-400",
                      displayAsSuperseded && "text-orange-600 dark:text-orange-400",
                      feature.status === 'tested' && "text-blue-600 dark:text-blue-400",
                      feature.status === 'defined' && "text-gray-500 dark:text-gray-500"
                    )}>
                      {totalTasks > 0
                        ? hasSupersededTasks
                          ? `${completedTasks}/${totalTasks} implemented (${supersededTasks} skipped)`
                          : `${doneTasks}/${totalTasks} tasks`
                        : 'No tasks'}
                    </div>

                    {/* Progress percentage for in-progress features */}
                    {feature.status === 'tested' && (
                      <div className={clsx(
                        "text-lg font-bold ml-3 flex-shrink-0",
                        "text-blue-700 dark:text-blue-300"
                      )}>
                        {progress}%
                      </div>
                    )}

                    {/* Status badge */}
                    {displayAsCompleted && (
                      <div className="text-sm font-medium text-green-700 dark:text-green-300 ml-3 flex-shrink-0">
                        Complete
                      </div>
                    )}
                    {displayAsSuperseded && (
                      <div className="text-sm font-medium text-orange-700 dark:text-orange-300 ml-3 flex-shrink-0">
                        Superseded
                      </div>
                    )}
                  </div>
                </div>

                {/* Feature Detail - Expandable */}
                {isExpanded && (
                  <div className="relative border-t border-current/20 bg-white/50 dark:bg-black/20">
                    <FeatureDetail
                      feature={feature}
                      onTaskClick={repoId ? handleTaskClick : undefined}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Task Detail Panel - only render when task is selected */}
      {repoId && plan.prdId && selectedTask && (
        <TaskDetailPanel
          isOpen={true}
          onClose={handleCloseTaskPanel}
          repoId={repoId}
          planId={plan.prdId}
          featureId={selectedTask.featureId}
          taskNumber={selectedTask.taskNumber}
          progressTask={selectedTask.progressTask}
        />
      )}
    </div>
  );
};

export default PlanDetailsPRD;
