interface GradePillProps {
  grade: string;
  score?: number;
  size?: 'sm' | 'lg';
}

const gradeStyles: Record<string, { bg: string; text: string }> = {
  A: { bg: 'bg-green-200 dark:bg-green-900/50', text: 'text-green-800 dark:text-green-300' },
  B: { bg: 'bg-blue-200 dark:bg-blue-900/50', text: 'text-blue-800 dark:text-blue-300' },
  C: { bg: 'bg-yellow-200 dark:bg-yellow-900/50', text: 'text-yellow-800 dark:text-yellow-300' },
  D: { bg: 'bg-orange-200 dark:bg-orange-900/50', text: 'text-orange-800 dark:text-orange-300' },
  E: { bg: 'bg-rose-200 dark:bg-rose-900/50', text: 'text-rose-800 dark:text-rose-300' },
  F: { bg: 'bg-red-200 dark:bg-red-900/50', text: 'text-red-800 dark:text-red-300' },
};

const defaultStyle = { bg: 'bg-gray-200 dark:bg-gray-700', text: 'text-gray-800 dark:text-gray-300' };

export default function GradePill({ grade, score, size = 'sm' }: GradePillProps) {
  const style = gradeStyles[grade] || defaultStyle;

  const sizeClasses = size === 'lg'
    ? 'px-4 py-2 text-lg font-bold'
    : 'px-2 py-0.5 text-xs font-medium';

  return (
    <span className={`rounded-full ${sizeClasses} ${style.bg} ${style.text}`}>
      {score !== undefined ? `${grade} / ${score}` : grade}
    </span>
  );
}
