import React, { useMemo, useState, useEffect } from 'react';
import type { Plan } from '../types';
import {
  extractMetrics,
  getRecentActivity
  // getFeatureMetrics, // TODO: Use for feature charts
} from '../utils/planMetrics';
import ProgressDonutChart from './charts/ProgressDonutChart';
import FeatureList from './FeatureList';
import Confetti from './Confetti';

interface PlanDetailsDashboardProps {
  plan: Plan;
}

const PlanDetailsDashboard: React.FC<PlanDetailsDashboardProps> = ({ plan }) => {
  // Process plan data into dashboard metrics
  const metrics = useMemo(() => extractMetrics(plan), [plan]);
  const recentActivity = useMemo(() => getRecentActivity(plan), [plan]);
  // const featureMetrics = useMemo(() => getFeatureMetrics(plan.features || []), [plan.features]); // TODO: Use for additional feature charts
  
  const isComplete = metrics.overallProgress === 100;
  const [showConfetti, setShowConfetti] = useState(false);
  const [hasShownConfetti, setHasShownConfetti] = useState<string | null>(null);

  // Show confetti only when plan transitions to complete (not when switching to already complete plan)
  useEffect(() => {
    // Only show confetti if:
    // 1. Plan is complete
    // 2. We haven't shown confetti for this specific plan yet
    // 3. This prevents showing on mount or when switching between plans
    if (isComplete && hasShownConfetti !== plan.id && metrics.completedFeatures > 0) {
      // Check if this is likely a transition to complete (not just viewing)
      const isNewlyComplete = plan.updatedAt &&
        new Date(plan.updatedAt).getTime() > Date.now() - 60000; // Within last minute

      if (isNewlyComplete) {
        setShowConfetti(true);
        setHasShownConfetti(plan.id);
        const timer = setTimeout(() => setShowConfetti(false), 5000);
        return () => clearTimeout(timer);
      }
    }
  }, [isComplete, plan.id, hasShownConfetti, metrics.completedFeatures, plan.updatedAt]);

  // Get current feature info
  const currentFeature = useMemo(() => {
    const features = plan.features || [];
    return features.find(p => p.status === 'tested') || features.find(p => p.status === 'defined');
  }, [plan.features]);

  const currentFeatureData = useMemo(() => {
    if (!currentFeature) return null;
    const totalTasks = currentFeature.tasks?.length || 0;
    const completedTasks = currentFeature.tasks?.filter(task => task.status === 'completed')?.length || 0;
    const incompleteTasks = currentFeature.tasks?.filter(task => task.status !== 'completed') || [];
    return {
      number: currentFeature.number,
      title: currentFeature.title,
      description: currentFeature.description,
      status: currentFeature.status,
      completedTasks,
      totalTasks,
      incompleteTasks,
      progress: totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0
    };
  }, [currentFeature]);

  return (
    <div className="p-3 space-y-3">
      {/* Confetti Effect */}
      {showConfetti && <Confetti />}
      
      {/* Completion Celebration Banner */}
      {isComplete && (
        <div className="bg-gradient-to-r from-green-500 to-emerald-500 dark:from-green-600 dark:to-emerald-600 rounded-lg p-4 text-white shadow-lg relative overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-shimmer-once pointer-events-none" />
          <div className="flex items-center justify-center gap-3">
            <span className="text-3xl">🎉</span>
            <div className="text-center">
              <h3 className="text-xl font-bold">Congratulations! Plan Complete!</h3>
              <p className="text-sm opacity-90 mt-1">All features and tasks have been successfully completed</p>
            </div>
            <span className="text-3xl">🎊</span>
          </div>
        </div>
      )}
      
      {/* Header - removed Details: prefix */}
      
      {/* Progress Overview Section */}
      <div className="bg-bg-primary dark:bg-gray-800 rounded-lg p-3 border border-border dark:border-gray-700">
        <h3 className="text-lg font-medium mb-4 text-gray-700 dark:text-gray-300">Progress Overview</h3>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          <div className="text-center p-2">
            <div className="text-xl sm:text-2xl font-bold text-blue-600">{metrics.completedFeatures}/{metrics.totalFeatures}</div>
            <div className="text-xs sm:text-sm text-text-secondary dark:text-gray-400">Features Complete</div>
          </div>

          <div className="text-center p-2">
            <div className="text-xl sm:text-2xl font-bold text-green-600">{metrics.completedTasks}/{metrics.totalTasks}</div>
            <div className="text-xs sm:text-sm text-text-secondary dark:text-gray-400">Total Tasks</div>
          </div>
          
          <div className="text-center p-2">
            <div className="text-xl sm:text-2xl font-bold text-purple-600">{metrics.overallProgress}%</div>
            <div className="text-xs sm:text-sm text-text-secondary dark:text-gray-400">Overall Progress</div>
          </div>
          
          <div className="text-center p-2">
            <div className="text-xl sm:text-2xl font-bold text-orange-600">{metrics.daysSinceCreated}</div>
            <div className="text-xs sm:text-sm text-text-secondary dark:text-gray-400">Days Active</div>
          </div>
        </div>
      </div>
      
      {/* Current Feature Section */}
      {currentFeatureData && (
        <div className="bg-bg-primary dark:bg-gray-800 rounded-lg p-3 border border-border dark:border-gray-700">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 mb-4">
            <h3 className="text-base sm:text-lg font-medium text-gray-700 dark:text-gray-300">
              Current Feature: Feature {currentFeatureData.number}
            </h3>
            <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${
              currentFeatureData.status === 'tested'
                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300'
                : 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300'
            }`}>
              {currentFeatureData.status === 'tested' ? 'In Progress' : 'Pending'}
            </span>
          </div>

          <div className="space-y-4">
            <div>
              <div className="text-xl font-normal text-gray-700 dark:text-gray-300">{currentFeatureData.title}</div>
              {currentFeatureData.description && (
                <div className="text-sm text-text-secondary dark:text-gray-400 mt-1">{currentFeatureData.description}</div>
              )}
            </div>

            <div className="flex items-center justify-between">
              <div className="text-sm text-text-secondary dark:text-gray-400">
                {currentFeatureData.completedTasks}/{currentFeatureData.totalTasks} tasks completed
              </div>
              <div className="text-2xl font-bold text-blue-600">{currentFeatureData.progress}%</div>
            </div>

            {currentFeatureData.totalTasks > 0 && (
              <div>
                <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                  <div
                    className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${currentFeatureData.progress}%` }}
                  />
                </div>
              </div>
            )}

            {currentFeatureData.incompleteTasks.length > 0 && (
              <div>
                <div className="text-sm font-medium text-text-primary dark:text-gray-200 mb-2">Next Tasks:</div>
                <div className="space-y-1">
                  {currentFeatureData.incompleteTasks.slice(0, 3).map((task, index) => (
                    <div key={index} className="flex items-start gap-2">
                      <span className="text-gray-400 mt-0.5">•</span>
                      <span className="text-sm text-text-secondary dark:text-gray-400">{task.description}</span>
                    </div>
                  ))}
                  {currentFeatureData.incompleteTasks.length > 3 && (
                    <div className="text-xs text-text-secondary dark:text-gray-500 pl-4">
                      +{currentFeatureData.incompleteTasks.length - 3} more tasks
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      )}
      
      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
        <div className="bg-bg-primary dark:bg-gray-800 rounded-lg p-3 border border-border dark:border-gray-700">
          <h3 className="text-base sm:text-lg font-medium mb-4 text-gray-700 dark:text-gray-300">Feature Completion</h3>
          <div className="max-w-[250px] sm:max-w-[300px] mx-auto">
            <ProgressDonutChart
              completed={metrics.completedFeatures}
              total={metrics.totalFeatures}
              label="Features"
            />
          </div>
        </div>

        <div className="bg-bg-primary dark:bg-gray-800 rounded-lg p-3 border border-border dark:border-gray-700">
          <h3 className="text-base sm:text-lg font-medium mb-4 text-gray-700 dark:text-gray-300">All Features</h3>
          <div className="h-[250px] sm:h-[300px]">
            <FeatureList
              features={plan.features || []}
              currentFeatureNumber={currentFeature?.number}
            />
          </div>
        </div>
      </div>
      
      {/* Recent Activity Section */}
      <div className="bg-bg-primary dark:bg-gray-800 rounded-lg p-3 border border-border dark:border-gray-700">
        <h3 className="text-base sm:text-lg font-medium mb-4 text-gray-700 dark:text-gray-300">Recent Activity</h3>
        <div className="space-y-2">
          {recentActivity.length > 0 ? recentActivity.map((activity, index) => (
            <div key={index} className="flex items-center gap-3 p-2 rounded bg-bg-secondary dark:bg-gray-700">
              <span className={`w-2 h-2 rounded-full ${
                activity.type === 'feature' ? 'bg-blue-500' : 'bg-green-500'
              }`}></span>
              <div className="flex-1">
                <div className="text-sm font-medium text-text-primary dark:text-gray-200">{activity.title}</div>
                {activity.featureTitle && (
                  <div className="text-xs text-text-secondary dark:text-gray-400">in {activity.featureTitle}</div>
                )}
              </div>
              <span className="text-xs text-green-600">✓</span>
            </div>
          )) : (
            <div className="text-text-secondary dark:text-gray-400 text-sm">No recent activity</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PlanDetailsDashboard;