import React from 'react';
import GradePill from './GradePill';
import type { QualityRunSummary } from '../types';

interface QualityListProps {
  runs: QualityRunSummary[];
  selectedRunId: string | null;
  onSelectRun: (runId: string) => void;
}

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

function formatIssueCount(count: number): string {
  return count === 1 ? '1 issue' : `${count} issues`;
}

const QualityList: React.FC<QualityListProps> = ({ runs, selectedRunId, onSelectRun }) => {
  if (runs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">📊</div>
        <p className="text-text-secondary text-center">No quality runs</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Use /quality skill to analyze your codebase
        </p>
      </div>
    );
  }

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Quality runs">
      {runs.map((run) => (
        <div
          key={run.runId}
          data-selected={run.runId === selectedRunId}
          className={`p-3 rounded-lg cursor-pointer transition-colors ${
            run.runId === selectedRunId
              ? 'bg-surface-highlight border border-accent'
              : 'bg-surface-secondary hover:bg-surface-highlight border border-transparent'
          }`}
          onClick={() => onSelectRun(run.runId)}
        >
          <div className="flex items-center justify-between mb-2">
            <span className="text-gray-900 dark:text-gray-100 font-medium">
              {formatDate(run.date)}
            </span>
            <GradePill grade={run.grade} />
          </div>
          <div className="flex items-center justify-between text-sm">
            <span className="text-gray-600 dark:text-gray-400">Score: {run.score}</span>
            <span className="text-gray-500 dark:text-gray-500">{formatIssueCount(run.issueCount)}</span>
          </div>
        </div>
      ))}
    </div>
  );
};

export default QualityList;
