import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, Circle, GitCommit, ExternalLink, TestTube, RefreshCw, FastForward } from 'lucide-react';
import type { Feature } from '../types';
import CommitDetailsPopover from './CommitDetailsPopover';

interface FeatureDetailProps {
  feature: Feature;
  onTaskClick?: (featureId: string, taskIndex: number, task: Feature['tasks'][0]) => void;
}

const FeatureDetail: React.FC<FeatureDetailProps> = ({ feature, onTaskClick }) => {
  const completedTasks = feature.tasks?.filter(t => t.status === 'completed').length || 0;
  const supersededTasks = feature.tasks?.filter(t => t.status === 'superseded').length || 0;
  const doneTasks = completedTasks + supersededTasks;
  const totalTasks = feature.tasks?.length || 0;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;

  return (
    <div className="p-4 space-y-3">
      {/* Feature Description */}
      {feature.description && (
        <div className="px-3 py-2 bg-muted/50 rounded-md">
          <p className="text-sm text-muted-foreground">{feature.description}</p>
        </div>
      )}

      {/* Tasks List */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              <GitCommit className="h-4 w-4" />
              Tasks
            </CardTitle>
            <span className="text-xs text-muted-foreground">
              {doneTasks}/{totalTasks}
              {supersededTasks > 0 && (
                <span className="ml-1 text-orange-500" title={`${supersededTasks} superseded`}>
                  ({supersededTasks} skipped)
                </span>
              )}
            </span>
          </div>
        </CardHeader>
        <CardContent>
          {totalTasks > 0 ? (
            <ul className="space-y-3">
              {feature.tasks?.map((task, index) => (
                <li
                  key={task.id}
                  className={`flex items-start gap-3 group ${
                    onTaskClick
                      ? 'cursor-pointer -mx-2 px-2 py-2 rounded-lg transition-all duration-150 hover:bg-blue-50 dark:hover:bg-blue-900/30 hover:shadow-sm hover:border-blue-200 dark:hover:border-blue-800 border border-transparent'
                      : ''
                  }`}
                  onClick={() => onTaskClick?.(feature.id, index + 1, task)}
                >
                  {/* TDD Phase Indicator */}
                  {task.status === 'completed' ? (
                    <div className="mt-0.5" title="GREEN: Implementation complete">
                      <CheckCircle2 className="h-5 w-5 text-green-500 flex-shrink-0" />
                    </div>
                  ) : task.status === 'superseded' ? (
                    <div className="mt-0.5" title="SUPERSEDED: Task no longer required">
                      <FastForward className="h-5 w-5 text-orange-500 flex-shrink-0" />
                    </div>
                  ) : task.status === 'tested' ? (
                    <div className="mt-0.5" title="RED: Tests written, awaiting implementation">
                      <CheckCircle2 className="h-5 w-5 text-red-500 flex-shrink-0" />
                    </div>
                  ) : (
                    <div className="mt-0.5" title="GRAY: Defined, no commits yet">
                      <Circle className="h-5 w-5 text-gray-400 flex-shrink-0" />
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm ${task.status === 'superseded' ? 'text-muted-foreground line-through' : ''}`}>
                      {task.description}
                    </p>
                    {/* Superseded note */}
                    {task.status === 'superseded' && task.note && (
                      <p className="text-xs text-orange-600 dark:text-orange-400 mt-1">
                        {task.note}
                      </p>
                    )}
                    {/* TDD Phase Commits */}
                    <div className="flex flex-wrap items-center gap-3 mt-1">
                      {/* Test Phase (Red) */}
                      {task.testCommitSha && (
                        <CommitDetailsPopover
                          commitSha={task.testCommitSha}
                          commitType="test"
                        >
                          <span className="text-xs text-red-600 hover:text-red-800 dark:text-red-400 dark:hover:text-red-300 font-mono flex items-center gap-1 cursor-pointer">
                            <TestTube className="h-3 w-3" />
                            {task.testCommitSha.substring(0, 7)}
                            <ExternalLink className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </span>
                        </CommitDetailsPopover>
                      )}

                      {/* Implementation Phase (Green) */}
                      {task.commitSha && (
                        <CommitDetailsPopover
                          commitSha={task.commitSha}
                          commitType="feat"
                        >
                          <span className="text-xs text-green-600 hover:text-green-800 dark:text-green-400 dark:hover:text-green-300 font-mono flex items-center gap-1 cursor-pointer">
                            <GitCommit className="h-3 w-3" />
                            {task.commitSha.substring(0, 7)}
                            <ExternalLink className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </span>
                        </CommitDetailsPopover>
                      )}

                      {/* Refactor Phase */}
                      {task.refactorCommitSha && (
                        <CommitDetailsPopover
                          commitSha={task.refactorCommitSha}
                          commitType="refactor"
                        >
                          <span className="text-xs text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 font-mono flex items-center gap-1 cursor-pointer">
                            <RefreshCw className="h-3 w-3" />
                            {task.refactorCommitSha.substring(0, 7)}
                            <ExternalLink className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </span>
                        </CommitDetailsPopover>
                      )}
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-sm text-muted-foreground text-center py-4">
              No tasks defined for this feature
            </p>
          )}
        </CardContent>
      </Card>

      {/* Feature Timeline */}
      {(feature.startedAt || feature.completedAt) && (
        <Card>
          <CardContent className="pt-4">
            <div className="relative">
              {/* Progress percentage above the bar */}
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs text-muted-foreground">Progress</span>
                <span className="text-sm font-semibold">{progress}%</span>
              </div>

              {/* Timeline bar - matching sidebar style */}
              <div className="relative h-2 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
                <div
                  className="absolute inset-y-0 left-0 transition-all duration-300"
                  style={{
                    width: `${feature.completedAt ? 100 : progress}%`,
                    backgroundColor: feature.status === 'completed' ? '#10b981' :
                                   feature.status === 'tested' ? '#3b82f6' : '#9ca3af'
                  }}
                />
              </div>

              {/* Timeline dates below bar */}
              <div className="flex justify-between mt-3 text-xs text-muted-foreground">
                {feature.startedAt && (
                  <span>{new Date(feature.startedAt).toLocaleDateString()}</span>
                )}
                {feature.completedAt && (
                  <span>{new Date(feature.completedAt).toLocaleDateString()}</span>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default FeatureDetail;
